export declare const streamCss = "\n.bs-stream .bs-status {\n  font-size: 0.85rem;\n  color: var(--gray);\n  margin: 0 0 0.75rem;\n}\n.bs-stream .bs-count {\n  font-weight: 600;\n  color: var(--darkgray);\n}\n.bs-feed {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 1.25rem;\n}\n.bs-feed > .bs-item[hidden] { display: none; }\n\n.bs-group {\n  margin: 1rem 0 0;\n  padding: 0;\n}\n.bs-group:first-child { margin-top: 0; }\n.bs-group h2 {\n  margin: 0;\n  padding-bottom: 0.3rem;\n  font-size: 0.95rem;\n  font-weight: 600;\n  letter-spacing: 0.03em;\n  color: var(--secondary);\n  border-bottom: 1px solid var(--lightgray);\n}\n\n.bs-item {\n  padding: 1rem 1.15rem 1.15rem;\n  border: 1px solid var(--lightgray);\n  border-radius: 8px;\n  background: var(--light);\n  transition: border-color 0.15s ease;\n  /* \u5361\u7247\u662F\u7B14\u8BB0\u5168\u6587\uFF0C\u4E00\u9875\u4E0A\u767E\u5F20\u7684\u8BDD DOM \u5F88\u91CD\uFF08KaTeX \u5C24\u5176\u5570\u55E6\uFF09\u3002\n     \u8BA9\u6D4F\u89C8\u5668\u8DF3\u8FC7\u89C6\u53E3\u5916\u5361\u7247\u7684\u6E32\u67D3\uFF0C\u6EDA\u5230\u4E86\u518D\u7B97\uFF1BCtrl+F \u548C textContent \u4E0D\u53D7\u5F71\u54CD\u3002 */\n  content-visibility: auto;\n  contain-intrinsic-size: auto 420px;\n}\n.bs-item:hover { border-color: var(--gray); }\n\n.bs-head {\n  padding-bottom: 0.6rem;\n  margin-bottom: 0.8rem;\n  border-bottom: 1px solid var(--lightgray);\n}\n\n.bs-title {\n  margin: 0 0 0.4rem;\n  font-size: 1.05rem;\n  line-height: 1.35;\n}\n.bs-title a { background-color: transparent; }\n\n.bs-meta {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.35rem;\n}\n.bs-date {\n  font-size: 0.78rem;\n  color: var(--gray);\n  font-variant-numeric: tabular-nums;\n  margin-right: 0.15rem;\n}\n.bs-chip {\n  font-size: 0.72rem;\n  line-height: 1.6;\n  padding: 0 0.5rem;\n  border-radius: 999px;\n  background: var(--highlight);\n  color: var(--darkgray);\n  white-space: nowrap;\n  max-width: 14rem;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n.bs-chip-label {\n  color: var(--gray);\n  margin-right: 0.25rem;\n}\n\n/* \u5361\u7247\u6B63\u6587\u5C31\u662F\u7B14\u8BB0\u5168\u6587\uFF0C\u6837\u5F0F\u8DDF\u7740\u7AD9\u70B9\u4E3B\u6837\u5F0F\u8D70\uFF0C\u53EA\u538B\u4E00\u70B9\u5B57\u53F7\u548C\u7559\u767D */\n.bs-content {\n  font-size: 0.92rem;\n  overflow-wrap: break-word;\n}\n.bs-content > :first-child { margin-top: 0; }\n.bs-content > :last-child { margin-bottom: 0; }\n.bs-content p { margin: 0.7em 0; line-height: 1.7; }\n\n.bs-content h1,\n.bs-content h2,\n.bs-content h3,\n.bs-content h4,\n.bs-content h5,\n.bs-content h6 {\n  /* \u7B14\u8BB0\u91CC\u7684\u6807\u9898\u5C42\u7EA7\u5728 feed \u91CC\u6CA1\u6709\u610F\u4E49\uFF0C\u538B\u5E73\u6210\u5C0F\u6807\u9898\u514D\u5F97\u76D6\u8FC7\u5361\u7247\u6807\u9898 */\n  font-size: 0.95rem;\n  font-weight: 600;\n  margin: 1.1em 0 0.4em;\n  color: var(--dark);\n}\n\n.bs-content img {\n  display: block;\n  max-width: 100%;\n  height: auto;\n  margin: 0.8em 0;\n  border-radius: 5px;\n}\n\n.bs-content pre,\n.bs-content .table-container,\n.bs-content table {\n  max-width: 100%;\n  overflow-x: auto;\n}\n\n/* \u884C\u95F4\u516C\u5F0F\u592A\u957F\u65F6\u8BA9\u5B83\u81EA\u5DF1\u6A2A\u5411\u6EDA\uFF0C\u522B\u628A\u6574\u9875\u6491\u5BBD */\n.bs-content .katex-display {\n  overflow-x: auto;\n  overflow-y: hidden;\n  padding: 0.2em 0;\n}\n\n.bs-content blockquote {\n  margin: 0.8em 0;\n  font-size: 0.95em;\n}\n.bs-content ul,\n.bs-content ol { margin: 0.6em 0; }\n\n.bs-empty {\n  color: var(--gray);\n  font-size: 0.9rem;\n  padding: 2rem 0;\n  text-align: center;\n}\n\n@media all and (max-width: 600px) {\n  .bs-item { padding: 0.85rem 0.9rem 1rem; }\n  .bs-content { font-size: 0.88rem; }\n}\n";
export declare const controlsCss = "\n.bs-controls[hidden] { display: none; }\n.bs-controls {\n  display: flex;\n  flex-direction: column;\n  gap: 0.85rem;\n  font-size: 0.85rem;\n  max-height: 100%;\n  overflow-y: auto;\n  overscroll-behavior: contain;\n}\n\n.bs-panel-header {\n  display: flex;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 0.5rem;\n}\n.bs-panel-title {\n  margin: 0;\n  font-size: 1rem;\n}\n.bs-reset {\n  border: none;\n  background: none;\n  padding: 0;\n  font-size: 0.78rem;\n  color: var(--secondary);\n  cursor: pointer;\n  font-family: inherit;\n}\n.bs-reset:disabled { color: var(--gray); cursor: default; }\n\n.bs-search,\n.bs-sort select,\n.bs-range-input {\n  font-family: inherit;\n  font-size: 0.82rem;\n  color: var(--darkgray);\n  background: var(--light);\n  border: 1px solid var(--lightgray);\n  border-radius: 5px;\n  padding: 0.3rem 0.45rem;\n  min-width: 0;\n}\n.bs-search { width: 100%; }\n.bs-search:focus-visible,\n.bs-sort select:focus-visible,\n.bs-range-input:focus-visible {\n  outline: 2px solid var(--secondary);\n  outline-offset: -1px;\n}\n\n.bs-sort {\n  display: flex;\n  align-items: center;\n  gap: 0.4rem;\n}\n.bs-sort-label {\n  flex: 0 0 2.2rem;\n  color: var(--gray);\n  font-size: 0.78rem;\n}\n.bs-sort select { flex: 1 1 auto; }\n.bs-sort-dir {\n  flex: 0 0 auto;\n  width: 1.9rem;\n  height: 1.75rem;\n  border: 1px solid var(--lightgray);\n  border-radius: 5px;\n  background: var(--light);\n  color: var(--darkgray);\n  cursor: pointer;\n  font-size: 0.9rem;\n  line-height: 1;\n}\n.bs-sort-dir:hover { border-color: var(--gray); }\n\n.bs-facet {\n  border-top: 1px solid var(--lightgray);\n  padding-top: 0.7rem;\n}\n.bs-facet-title {\n  margin: 0 0 0.4rem;\n  font-size: 0.8rem;\n  font-weight: 600;\n  color: var(--secondary);\n}\n.bs-facet-values {\n  display: flex;\n  flex-direction: column;\n  gap: 0.15rem;\n}\n.bs-facet-value {\n  display: flex;\n  align-items: center;\n  gap: 0.4rem;\n  cursor: pointer;\n  padding: 0.1rem 0;\n  line-height: 1.4;\n}\n.bs-facet-value input { margin: 0; flex: 0 0 auto; accent-color: var(--secondary); }\n.bs-facet-label {\n  flex: 1 1 auto;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  font-size: 0.8rem;\n}\n.bs-facet-count {\n  flex: 0 0 auto;\n  font-size: 0.72rem;\n  color: var(--gray);\n  font-variant-numeric: tabular-nums;\n}\n\n.bs-facet .bs-overflow { display: none; }\n.bs-facet.bs-expanded .bs-overflow { display: flex; }\n.bs-more {\n  margin-top: 0.3rem;\n  border: none;\n  background: none;\n  padding: 0;\n  font-family: inherit;\n  font-size: 0.75rem;\n  color: var(--secondary);\n  cursor: pointer;\n}\n\n.bs-range {\n  display: flex;\n  align-items: center;\n  gap: 0.3rem;\n}\n.bs-range-input { flex: 1 1 0; width: 100%; }\n.bs-range-dash { color: var(--gray); flex: 0 0 auto; }\n";
